CREATE TABLE public.gryt_payment_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, sku text NOT NULL UNIQUE, amount_cents integer NOT NULL CHECK (amount_cents > 0), description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.gryt_payment_products TO service_role;
ALTER TABLE public.gryt_payment_products ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.gryt_ticket_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug !~* '(saturday|weekly-run)'), name text NOT NULL, event_date timestamptz NOT NULL, location text NOT NULL, amount_cents integer NOT NULL CHECK (amount_cents > 0), capacity integer NOT NULL CHECK (capacity > 0), active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.gryt_ticket_events TO service_role;
ALTER TABLE public.gryt_ticket_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.gryt_partner_packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL UNIQUE, partner_name text NOT NULL, name text NOT NULL, amount_cents integer NOT NULL CHECK (amount_cents > 0), description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.gryt_partner_packages TO service_role;
ALTER TABLE public.gryt_partner_packages ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.gryt_payment_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL CHECK (type IN ('support','merch','ticket','partner')), item_id uuid, item text NOT NULL, amount_cents integer NOT NULL CHECK (amount_cents >= 500), quantity integer NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 10), email text NOT NULL, attendee_name text NOT NULL DEFAULT '', fulfillment text NOT NULL DEFAULT '', monthly boolean NOT NULL DEFAULT false, return_path text NOT NULL, stripe_session_id text UNIQUE, stripe_customer_id text, stripe_subscription_id text, status text NOT NULL DEFAULT 'reserved' CHECK (status IN ('reserved','pending','paid','failed','expired')), environment text NOT NULL DEFAULT 'sandbox' CHECK (environment = 'sandbox'), expires_at timestamptz NOT NULL DEFAULT (now() + interval '31 minutes'), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.gryt_payment_orders TO service_role;
ALTER TABLE public.gryt_payment_orders ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type text NOT NULL, amount integer NOT NULL, email text NOT NULL, item text NOT NULL, stripe_session_id text, stripe_invoice_id text UNIQUE, stripe_event_id text NOT NULL UNIQUE, order_id uuid REFERENCES public.gryt_payment_orders(id), status text NOT NULL, environment text NOT NULL DEFAULT 'sandbox' CHECK (environment = 'sandbox'), created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.payments TO service_role;
ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX gryt_payment_session_once ON public.payments(stripe_session_id) WHERE stripe_session_id IS NOT NULL;
CREATE INDEX gryt_orders_event_capacity ON public.gryt_payment_orders(item_id,status,expires_at);
CREATE FUNCTION public.gryt_test_catalog(event_slug text DEFAULT '') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('products', COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'sku',sku,'amount_cents',amount_cents,'description',description)) FROM public.gryt_payment_products WHERE active), '[]'::jsonb), 'event', (SELECT jsonb_build_object('id',e.id,'slug',e.slug,'name',e.name,'event_date',e.event_date,'location',e.location,'amount_cents',e.amount_cents,'capacity',e.capacity,'remaining',GREATEST(0,e.capacity-COALESCE((SELECT sum(o.quantity) FROM public.gryt_payment_orders o WHERE o.item_id=e.id AND o.type='ticket' AND (o.status IN ('paid','pending') OR (o.status='reserved' AND o.expires_at>now()))),0))) FROM public.gryt_ticket_events e WHERE e.active AND e.slug=event_slug)) $$;
REVOKE ALL ON FUNCTION public.gryt_test_catalog(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.gryt_test_catalog(text) TO anon, authenticated, service_role;
CREATE FUNCTION public.gryt_reserve_test_order(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; available integer; requested integer; result uuid; BEGIN target := NULLIF(payload->>'item_id','')::uuid; requested := (payload->>'quantity')::integer; IF payload->>'type'='ticket' THEN PERFORM 1 FROM public.gryt_ticket_events WHERE id=target AND active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'EVENT_UNAVAILABLE'; END IF; SELECT capacity-COALESCE((SELECT sum(quantity) FROM public.gryt_payment_orders WHERE item_id=target AND type='ticket' AND (status IN ('paid','pending') OR (status='reserved' AND expires_at>now()))),0) INTO available FROM public.gryt_ticket_events WHERE id=target; IF requested>available THEN RAISE EXCEPTION 'EVENT_SOLD_OUT'; END IF; ELSIF payload->>'type'='partner' THEN PERFORM 1 FROM public.gryt_partner_packages WHERE id=target AND active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'PACKAGE_UNAVAILABLE'; END IF; IF EXISTS(SELECT 1 FROM public.gryt_payment_orders WHERE item_id=target AND type='partner' AND (status IN ('paid','pending') OR (status='reserved' AND expires_at>now()))) THEN RAISE EXCEPTION 'PACKAGE_ALREADY_RESERVED_OR_PAID'; END IF; END IF; INSERT INTO public.gryt_payment_orders(type,item_id,item,amount_cents,quantity,email,attendee_name,fulfillment,monthly,return_path) VALUES(payload->>'type',target,payload->>'item',(payload->>'amount_cents')::integer,requested,payload->>'email',COALESCE(payload->>'attendee_name',''),COALESCE(payload->>'fulfillment',''),COALESCE((payload->>'monthly')::boolean,false),payload->>'return_path') RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.gryt_reserve_test_order(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.gryt_reserve_test_order(jsonb) TO service_role;
